        left, right = min(c for r, c in pts), max(c for r, c in pts)
        pattern = [[grid[r][c] if grid[r][c] == color else 0
                    for c in range(left, right + 1)]
                   for r in range(top, bottom + 1)]
        source_marker = (bottom + 1, right + 1)
        templates[grid[source_marker[0]][source_marker[1]]] = pattern
    for r in range(h):
        for c in range(w):
            if (r, c) == source_marker or grid[r][c] not in templates:
