            stamp = templates[grid[r][c]]
            for dr in range(len(stamp)):
                for dc in range(len(stamp[0])):
                    if stamp[dr][dc] and r + dr < h and c + dc < w:
                        out[r + dr][c + dc] = stamp[dr][dc]
    return out
